(function(api){const b=api.basePath;let removed=0,active=0,timer=0,path="",level=15,onStart=0,onDone=0,oldVol=15,volSaved=0;function clearTimer(){if(timer){clearTimeout(timer);timer=0}}function saveVol(){if(volSaved)return;try{oldVol=Pip.settings&&typeof Pip.settings.volume==="number"?Pip.settings.volume:15}catch(error){oldVol=15}volSaved=1}function restoreVol(){if(!volSaved)return;try{Pip.setVol(oldVol)}catch(error){}volSaved=0}function duration(){return path==="LAZY_DAYS-TIRED_PREVIEW.WAV"?7680:path==="BOTTLE_CAP_PREVIEW.WAV"?2050:path==="GAME_OVER_WIN.WAV"?1650:1000}function finish(){let cb;if(!active)return;clearTimer();active=0;restoreVol();cb=onDone;onStart=0;onDone=0;if(cb)cb()}function start(p,vol,startedCb,doneCb){let v;stop();if(removed||vol<=0)return 0;path=p;level=vol;onStart=startedCb||0;onDone=doneCb||0;saveVol();try{v=Math.round(oldVol*level/15);if(v<0)v=0;Pip.setVol(v);Pip.audioStart(b+path);active=1;if(onStart)onStart();timer=setTimeout(finish,duration());return 1}catch(error){active=0;restoreVol();onStart=0;onDone=0;return 0}}function stop(){let was=active;clearTimer();if(was){try{Pip.audioStop()}catch(error){}}active=0;restoreVol();onStart=0;onDone=0}function remove(){if(removed)return;stop();removed=1}return{start:start,stop:stop,remove:remove,isActive:function(){return active},isWaiting:function(){return 0}}});